namespace ghidra.app.plugin.core.debug.gui.model;









using docking.widgets.table;
using docking.widgets.table;
using ghidra.app.plugin.core.debug.gui.model.ObjectTableModel;
using ghidra.framework.plugintool;
using ghidra.trace.model;
using ghidra.trace.model.target;
using ghidra.trace.model.target.schema;

public class ObjectsTablePanel : AbstractQueryTablePanel<ValueRow, ObjectTableModel> {

	private static readonly string DEFAULT_PREF_KEY = "DEFAULT";

	private static class PropertyEditor : GTableTextCellEditor {
		private JTextField textField;

		public PropertyEditor() : base(new JTextField())
    {
			textField = (JTextField) getComponent();
		}

		/* @Override */
		public Component getTableCellEditorComponent(JTable table, object value, bool isSelected,
				int row, int column) {
			base.getTableCellEditorComponent(table, value, isSelected, row, column);
			if (value is ValueProperty<object> property) {
				textField.setText(property.getDisplay());
			}
			else {
				textField.setText(value.toString());
			}
			return textField;
		}

		/* @Override */
		public object getCellEditorValue() {
			object value = base.getCellEditorValue();
			return new(value);
		}
	}

	public ObjectsTablePanel(Plugin plugin) : base(plugin)
    {
		table.setDefaultEditor(typeof(ValueProperty), new PropertyEditor());
	}

	/* @Override */
	protected ObjectTableModel createModel() {
		return new ObjectTableModel(plugin);
	}

	public bool trySelectAncestor(TraceObject successor) {
		ValueRow row = tableModel.findTraceObjectAncestor(successor);
		if (row == null) {
			return false;
		}
		setSelectedItem(row);
		return true;
	}

	protected string computePreferenceKey() {
		Trace trace = tableModel.getTrace();
		if (trace == null) {
			return DEFAULT_PREF_KEY;
		}
		ModelQuery query = tableModel.getQuery();
		if (query == null) {
			return DEFAULT_PREF_KEY;
		}
		List<TraceObjectSchema> schemas = query.computeSchemas(trace);
		if (schemas.isEmpty()) {
			return DEFAULT_PREF_KEY;
		}
		TraceObjectSchema rootSchema = trace.getObjectManager().getRootSchema();
		if (rootSchema == null) {
			return DEFAULT_PREF_KEY;
		}
		return rootSchema.getName() + ":" + schemas
				.stream()
				.map(s => s.getName().toString())
				.collect(Collectors.joining(",")) +
			":" + (isShowHidden() ? "show" : "hide");
	}

	protected void showHiddenColumns(bool show) {
		if (table.getColumnModel() is GTableColumnModel columnModel) {
			foreach (TableColumn tCol in columnModel.getAllColumns()) {
				int modelIndex = tCol.getModelIndex();
				if (tableModel
						.getColumn(modelIndex) is AutoAttributeColumn<object> attrCol) {
					if (attrCol.isHidden()) {
						columnModel.setVisible(tCol, show);
					}
				}
			}
		}
	}

	protected void reloadPreferences() {
		string prefKey = computePreferenceKey();
		if (!prefKey.equals(table.getPreferenceKey())) {
			table.setPreferenceKey(prefKey);
		}
	}

	protected void resyncAttributeVisibility() {
		showHiddenColumns(isShowHidden());
	}

	/* @Override */
	protected void coordinatesChanged() {
		base.coordinatesChanged();
		reloadPreferences();
	}

	/* @Override */
	protected void queryChanged() {
		base.queryChanged();
		reloadPreferences();
	}

	/* @Override */
	protected void showHiddenChanged() {
		base.showHiddenChanged();
		resyncAttributeVisibility();
	}
}
